 "<b style=\"font-size:24px;color:#2e9b73\">Constante</b><br><span style=\"font-size:20px;color:#13203a\">Se queda en el mismo valor.</span>": "<b style=\"font-size:24px;color:#2e9b73\">Constant</b><br><span style=\"font-size:20px;color:#13203a\">Blijft op dezelfde waarde.</span>",
